import { Component, OnInit } from '@angular/core';
import { DestinationService } from '../../../services/destination.service';
import { Destination } from '../../../models/destination.model';

@Component({
    selector: 'app-suggestions',
    templateUrl: './suggestions.component.html',
    styleUrls: ['./suggestions.component.css']
})
export class SuggestionsComponent implements OnInit {
    suggestions: any[] = [];
    loading = false;
    error = '';
    successMessage = '';

    constructor(private destinationService: DestinationService) { }

    ngOnInit(): void {
        this.loadSuggestions();
    }

    loadSuggestions() {
        this.loading = true;
        this.destinationService.getSuggestions()
            .subscribe({
                next: (response) => {
                    this.suggestions = response.data; // backend returns list of Destination
                    this.loading = false;
                },
                error: (e) => {
                    this.error = 'Failed to load suggestions from backend API';
                    this.loading = false;
                    console.error(e);
                }
            });
    }

    addToDatabase(destination: any) {
        // Backend returns ready Destination objects now, so we can use them directly
        if (!confirm(`Add ${destination.country} to your destinations?`)) return;

        // Use the destination object directly
        this.destinationService.addDestination(destination)
            .subscribe({
                next: () => {
                    this.successMessage = `${destination.country} added successfully!`;
                    // Remove from list
                    this.suggestions = this.suggestions.filter(s => s.country !== destination.country);
                    setTimeout(() => this.successMessage = '', 3000);
                },
                error: (err) => {
                    alert('Failed to add destination. It might already exist.');
                    console.error(err);
                }
            });
    }
}
